// İlk olarak veri doğrulama ve loglama
const items = $input.all();
console.log(`[INFO] Processing ${items.length} call records`);

if (items.length === 0) {
  console.log('[WARNING] No call records found to process');
  return [];
}

// Her kayıt için detaylı validation
const validatedItems = [];
const errorItems = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const callData = item.json;

  console.log(`[INFO] Validating call record ${i + 1}/${items.length}:`, {
    callid: callData.callid,
    url: callData.url,
    created_at: callData.created_at
  });

  // Zorunlu alanları kontrol et
  const errors = [];

  if (!callData.callid) {
    errors.push('Missing callid');
  }

  if (!callData.url || typeof callData.url !== 'string') {
    errors.push('Missing or invalid URL');
  }

  // URL erişilebilirlik kontrolü için format kontrolü
  if (callData.url && !callData.url.startsWith('http')) {
    errors.push('Invalid URL format - must start with http/https');
  }

  if (errors.length > 0) {
    console.log(`[ERROR] Call ${callData.callid} validation failed:`, errors);
    errorItems.push({
      ...callData,
      validation_errors: errors,
      error_timestamp: new Date().toISOString()
    });
  } else {
    console.log(`[SUCCESS] Call ${callData.callid} validation passed`);
    validatedItems.push(item);
  }
}

// Hata kayıtlarını ayrı bir outputa gönder
if (errorItems.length > 0) {
  console.log(`[WARNING] ${errorItems.length} records failed validation`);
  // Bu kayıtları veritabanında error olarak işaretle
}

console.log(`[INFO] ${validatedItems.length} records passed validation`);
return validatedItems;

// HTTP isteği sonrası detaylı kontrol ve loglama
const item = $input.first();
const response = item.json;

console.log('[INFO] HTTP Request completed for call:', {
  callid: response.callid,
  url: response.url,
  statusCode: response.$response?.statusCode,
  contentLength: response.$response?.headers?.['content-length'],
  contentType: response.$response?.headers?.['content-type']
});

// HTTP yanıt kontrolü
if (!response.$response) {
  console.log('[ERROR] No HTTP response received');
  throw new Error('HTTP request failed - no response');
}

const statusCode = response.$response.statusCode;
if (statusCode !== 200) {
  console.log(`[ERROR] HTTP request failed with status ${statusCode}`);
  throw new Error(`HTTP request failed with status ${statusCode}`);
}

// Binary data kontrolü
if (!item.binary || !item.binary.data) {
  console.log('[ERROR] No binary data received from HTTP request');
  throw new Error('No audio file data received');
}

const binarySize = item.binary.data.data?.length || 0;
console.log(`[SUCCESS] Binary data received: ${binarySize} bytes`);

// Minimum dosya boyutu kontrolü (1KB)
if (binarySize < 1024) {
  console.log(`[WARNING] File size suspiciously small: ${binarySize} bytes`);
}

return [item];

// Gelişmiş callDirection belirleme ve loglama
const item = $input.first();
const fileName = item.json.url || "";
let callDirection = "unknown";
let callid = item.json.callid || "";

console.log(`[INFO] Processing file direction detection for:`, {
  callid: callid,
  url: fileName
});

// URL içinde direction kelimelerini ara (büyük/küçük harf duyarsız)
const urlLower = fileName.toLowerCase();

if (urlLower.includes("inbound")) {
  callDirection = "inbound";
  console.log(`[INFO] Direction detected as INBOUND from URL`);
} else if (urlLower.includes("outbound")) {
  callDirection = "outbound";
  console.log(`[INFO] Direction detected as OUTBOUND from URL`);
} else if (urlLower.includes("incoming")) {
  callDirection = "inbound";
  console.log(`[INFO] Direction detected as INBOUND (from 'incoming')`);
} else if (urlLower.includes("outgoing")) {
  callDirection = "outbound";
  console.log(`[INFO] Direction detected as OUTBOUND (from 'outgoing')`);
} else {
  // Varsayılan olarak inbound kabul et ama uyarı ver
  callDirection = "inbound";
  console.log(`[WARNING] Could not determine call direction from URL, defaulting to INBOUND`);
}

// CallID doğrulama ve temizleme
if (!callid || callid.trim() === '') {
  // URL'den callid çıkarmaya çalış
  const match = fileName.match(/\/(([\w\-\.]+)\.(wav|mp3|m4a))$/i);
  if (match && match[2]) {
    callid = match[2];
    console.log(`[INFO] CallID extracted from URL: ${callid}`);
  } else {
    callid = 'unknown-' + Date.now();
    console.log(`[WARNING] Could not extract CallID, generated: ${callid}`);
  }
}

// Dosya formatı kontrolü
const supportedFormats = ['.wav', '.mp3', '.m4a'];
const hasValidFormat = supportedFormats.some(format => 
  fileName.toLowerCase().includes(format)
);

if (!hasValidFormat) {
  console.log(`[WARNING] Unsupported or unknown audio format in: ${fileName}`);
}

console.log(`[SUCCESS] File processing completed:`, {
  callid: callid,
  callDirection: callDirection,
  validFormat: hasValidFormat
});

// Tüm binary datayı ve json'ı koru, metadata ekle
return [{
  json: { 
    ...item.json, 
    callDirection,
    callid: callid,
    processedAt: new Date().toISOString(),
    fileFormat: fileName.split('.').pop()?.toLowerCase() || 'unknown'
  },
  binary: item.binary
}];

// S3 upload öncesi ön kontrol ve loglama
const item = $input.first();
const callid = item.json.callid;
const callDirection = item.json.callDirection;

console.log(`[INFO] Preparing S3 upload for ${callDirection} call:`, {
  callid: callid,
  direction: callDirection,
  hasBinaryData: !!item.binary?.data
});

// Binary data son kontrolü
if (!item.binary || !item.binary.data) {
  console.log(`[ERROR] No binary data available for upload - CallID: ${callid}`);
  throw new Error(`No binary data for CallID: ${callid}`);
}

// S3 dosya yolu oluştur
const s3Key = `calls/${callDirection}/${callid}.wav`;
const s3Path = `s3://callintech/${s3Key}`;

console.log(`[INFO] S3 upload details:`, {
  bucket: 'callintech',
  key: s3Key,
  fullPath: s3Path
});

return [{
  json: {
    ...item.json,
    s3Key: s3Key,
    s3Path: s3Path,
    uploadAttemptAt: new Date().toISOString()
  },
  binary: item.binary
}];

// S3 upload sonrası detaylı kontrol ve metadata hazırlama
const items = $input.all();
console.log(`[INFO] Processing ${items.length} S3 upload results`);

const processedItems = [];

for (const item of items) {
  const callid = item.json.callid;
  const wasError = !!item.json.error;

  console.log(`[INFO] Processing S3 result for CallID: ${callid}`);

  if (wasError) {
    console.log(`[ERROR] S3 upload failed for CallID ${callid}:`, item.json.error);

    // Hata durumunda retry bilgisi ekle
    processedItems.push({
      json: {
        ...item.json,
        s3_uploaded: false,
        upload_error: item.json.error,
        upload_failed_at: new Date().toISOString(),
        retry_count: (item.json.retry_count || 0) + 1
      }
    });
  } else {
    console.log(`[SUCCESS] S3 upload completed for CallID: ${callid}`);

    // S3 response'dan Location URL'ini al
    const s3Location = item.json.Location || item.json.s3Path;

    processedItems.push({
      json: {
        ...item.json,
        s3_uploaded: true,
        s3_path: s3Location || item.json.s3Path,
        file_url: s3Location,
        uploaded_at: new Date().toISOString(),
        upload_success: true
      }
    });
  }
}

console.log(`[INFO] Processed ${processedItems.length} upload results`);
return processedItems;

// Veritabanı güncelleme sonrası final loglama
const items = $input.all();

let successCount = 0;
let errorCount = 0;

for (const item of items) {
  const callid = item.json.callid;
  const s3Uploaded = item.json.s3_uploaded;

  if (s3Uploaded) {
    successCount++;
    console.log(`[SUCCESS] CallID ${callid} - Complete workflow success`);
  } else {
    errorCount++;
    console.log(`[ERROR] CallID ${callid} - Workflow completed with errors`);
  }
}

console.log(`[SUMMARY] Workflow completed:`, {
  totalProcessed: items.length,
  successful: successCount,
  failed: errorCount,
  timestamp: new Date().toISOString()
});

// Başarılı kayıtları döndür
return items;
